use super::*;

/// [`sync_document`] INTO A LANE — what a session bound to one must call.
///
/// Writes landed on `main` no matter which lane a session was bound to, because `save` reached
/// `sync_document` and that wrote `MAIN` unconditionally. `$BSC_GRAPH_LANE` was honoured on READ
/// (`document_in`) and by the `lane` verbs and the export, so a lane looked bound and isolated nothing:
/// every `impl set` from every session still met on `main`, which is exactly the shared-store collision
/// lanes were built to remove. MEASURED the day it was found: one branch's export pulled in 7 frontend
/// records it never authored plus a `folder` normalisation across 15 more, all arriving through `main`.
///
/// Reads are lane-over-main, so the comparison has to be too: a record the lane has not touched is
/// compared against MAIN's body, and only a record that actually differs gets a lane row. That is what
/// keeps a lane the median 4 rows it is supposed to be rather than a copy of the whole graph.
pub fn sync_document_in(
    conn: &Connection,
    lane: &str,
    doc: &Value,
    by: &str,
    note: Option<&str>,
) -> Result<Sync, String> {
    let mut out = Sync::default();
    let mut seen: std::collections::BTreeSet<String> = Default::default();
    for (key, tier) in [("implementations", TIER_IMPL), ("edges", TIER_EDGE)] {
        for rec in doc.get(key).and_then(Value::as_array).map(Vec::as_slice).unwrap_or(&[]) {
            let Some(id) = rec.get("id").and_then(Value::as_str) else { continue };
            seen.insert(id.to_string());
            let body = import::body_of(rec);
            // AS THE LANE SEES IT. `get_in` is already lane-over-main, so a record the lane has not
            // touched compares against MAIN's body and only a real difference mints a lane row — which
            // is what keeps a lane the median 4 rows rather than a copy of the whole graph.
            match get_in(conn, lane, id)? {
                Some(cur) if same_body(&cur, &body) => out.unchanged += 1,
                Some(_) => {
                    put_in(conn, lane, id, &body, Write::by(by).note(note).tier(tier))?;
                    out.changed += 1;
                }
                None => {
                    put_in(conn, lane, id, &body, Write::by(by).note(note).tier(tier))?;
                    out.added += 1;
                }
            }
        }
    }
    let live: Vec<String> = document_in(conn, lane)?
        .get("implementations")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[])
        .iter()
        .chain(
            document_in(conn, lane)?
                .get("edges")
                .and_then(Value::as_array)
                .map(Vec::as_slice)
                .unwrap_or(&[]),
        )
        .filter_map(|r| r.get("id").and_then(Value::as_str).map(str::to_string))
        .collect();
    for id in live {
        if !seen.contains(&id) {
            remove_in(conn, lane, &id, by, note)?;
            out.removed += 1;
        }
    }
    Ok(out)
}
